def count_aliens_fully_disinfected(N: int, M: int, H: list) -> int:
    cnt = 0
    for hands in H:
        if M >= hands:
            M -= hands
            cnt += 1
        else:
            break
    return cnt

# Example usage:
N, M = map(int, input().split())
H = list(map(int, input().split()))
print(count_aliens_fully_disinfected(N, M, H))
